package com.autoops.workflow.controller;import com.autoops.common.security.CurrentUser;import com.autoops.workflow.entity.Workflow;import com.autoops.workflow.repository.WorkflowRepository;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/workflows")public class WorkflowController{private final WorkflowRepository repo;private final CurrentUser current;public WorkflowController(WorkflowRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public List<Workflow> list(){return repo.findByCreatedByAndDeletedAtIsNull(current.id());}@PostMapping public Workflow create(@RequestBody Workflow w){w.setCreatedBy(current.id());return repo.save(w);}}
